<?php
 namespace QQWorld\Email\Test\Unit\Block\Adminhtml\Template\Grid\Renderer; class SenderTest extends \PHPUnit\Framework\TestCase { protected $sender; protected function setUp() { $objectManager = new \QQWorld\Framework\TestFramework\Unit\Helper\ObjectManager($this); $this->sender = $objectManager->getObject(\QQWorld\Email\Block\Adminhtml\Template\Grid\Renderer\Sender::class); } public function testRenderName() { $row = new \QQWorld\Framework\DataObject(); $row->setTemplateSenderName('Sender Name'); $this->assertEquals('Sender Name ', $this->sender->render($row)); } public function testRenderEmail() { $row = new \QQWorld\Framework\DataObject(); $row->setTemplateSenderEmail('Sender Email'); $this->assertEquals('[Sender Email]', $this->sender->render($row)); } public function testRenderNameAndEmail() { $row = new \QQWorld\Framework\DataObject(); $row->setTemplateSenderName('Sender Name'); $row->setTemplateSenderEmail('Sender Email'); $this->assertEquals('Sender Name [Sender Email]', $this->sender->render($row)); } public function testRenderEmpty() { $row = new \QQWorld\Framework\DataObject(); $this->assertEquals('---', $this->sender->render($row)); } } 